package com.example.text;

import java.util.concurrent.atomic.AtomicLong;
import java.util.List;
import java.util.Map;

/** Runs `Strings` and its Rust port side by side. Generated by carcinize: call it in place of `Strings`. */
public final class StringsShadow {
    private StringsShadow() {}

    private static final String MODE = System.getProperty("carcinize.mode", "shadow");
    public static final AtomicLong CALLS = new AtomicLong();
    public static final AtomicLong MISMATCHES = new AtomicLong();

    private static void compare(String name, Object expected, Object actual) {
        CALLS.incrementAndGet();
        if (actual instanceof Throwable || !carcinize.CarcinizeJson.write(expected).equals(carcinize.CarcinizeJson.write(actual))) {
            if (MISMATCHES.incrementAndGet() <= 10) {
                System.err.println("[carcinize] mismatch in " + name + ": expected " + expected + ", got " + actual);
            }
        }
    }

    public static String slugify(String text, int max) {
        if (MODE.equals("new")) {
            return (String) carcinize.TextRsNative.invoke("slugify", new carcinize.CarcinizeJson.TypeRef<String>() {}.type(), text, max);
        }
        String expected = Strings.slugify(text, max);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("slugify", new carcinize.CarcinizeJson.TypeRef<String>() {}.type(), text, max);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("slugify", expected, actual);
        }
        return expected;
    }

    public static List<String> words(String text) {
        if (MODE.equals("new")) {
            return (List<String>) carcinize.TextRsNative.invoke("words", new carcinize.CarcinizeJson.TypeRef<List<String>>() {}.type(), text);
        }
        List<String> expected = Strings.words(text);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("words", new carcinize.CarcinizeJson.TypeRef<List<String>>() {}.type(), text);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("words", expected, actual);
        }
        return expected;
    }

    public static Map<String, Integer> frequencies(String text) {
        if (MODE.equals("new")) {
            return (Map<String, Integer>) carcinize.TextRsNative.invoke("frequencies", new carcinize.CarcinizeJson.TypeRef<Map<String, Integer>>() {}.type(), text);
        }
        Map<String, Integer> expected = Strings.frequencies(text);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("frequencies", new carcinize.CarcinizeJson.TypeRef<Map<String, Integer>>() {}.type(), text);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("frequencies", expected, actual);
        }
        return expected;
    }

    public static int parsePort(String text) {
        if (MODE.equals("new")) {
            return (Integer) carcinize.TextRsNative.invoke("parsePort", new carcinize.CarcinizeJson.TypeRef<Integer>() {}.type(), text);
        }
        int expected = Strings.parsePort(text);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("parsePort", new carcinize.CarcinizeJson.TypeRef<Integer>() {}.type(), text);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("parsePort", expected, actual);
        }
        return expected;
    }

    public static int hash(String text) {
        if (MODE.equals("new")) {
            return (Integer) carcinize.TextRsNative.invoke("hash", new carcinize.CarcinizeJson.TypeRef<Integer>() {}.type(), text);
        }
        int expected = Strings.hash(text);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("hash", new carcinize.CarcinizeJson.TypeRef<Integer>() {}.type(), text);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("hash", expected, actual);
        }
        return expected;
    }
}
